def process(wollastonDatasheet) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = wollastonDatasheet.copy()

    # Promote first row to header
    header = df.iloc[0].astype(str).str.strip().tolist()
    df2 = df.iloc[1:].copy()
    df2.columns = header

    # If there are duplicate column names (e.g., repeated Tag/Enterococcus), keep first occurrence
    df2 = df2.loc[:, ~pd.Index(df2.columns).duplicated(keep='first')].copy()

    # Ensure expected columns exist
    needed = {'Date', '3-Day Rain', 'Tag', 'Enterococcus'}
    missing = needed - set(df2.columns)
    if missing:
        return pd.DataFrame([{
            'error': f"Missing expected columns after header promotion: {sorted(missing)}",
            'columns': list(df2.columns)[:50]
        }])

    # Parse date and rainfall
    out = pd.DataFrame({
        'date': pd.to_datetime(df2['Date'], errors='coerce'),
        'rainPast3Days': pd.to_numeric(df2['3-Day Rain'], errors='coerce'),
        'tag': df2['Tag'].astype('string').str.strip(),
        'enterococcusRaw': pd.to_numeric(df2['Enterococcus'], errors='coerce')
    })

    out['tag'] = out['tag'].replace({'<': '<', '>': '>'})

    def est(tag, x):
        if pd.isna(x):
            return np.nan
        if tag == '<':
            return x / 2.0
        if tag == '>':
            return float(x)
        return float(x)

    out['enterococcusEst'] = [est(t, x) for t, x in zip(out['tag'], out['enterococcusRaw'])]

    out = out.dropna(subset=['date', 'rainPast3Days', 'enterococcusEst']).copy()
    out['Community'] = 'Quincy'
    out['Beach Name'] = 'Wollaston Beach'

    return out[['Community', 'Beach Name', 'date', 'rainPast3Days', 'enterococcusEst']]

def process(wollastonDatasheet) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = wollastonDatasheet.copy()

    # First row contains the real headers
    new_header = df.iloc[0].astype(str).tolist()
    df2 = df.iloc[1:].copy()
    df2.columns = new_header

    # Drop duplicate columns if any
    df2 = df2.loc[:, ~pd.Index(df2.columns).duplicated(keep='first')].copy()

    # Expected columns for rainfall
    for c in ['1-Day Rain', '2-Day Rain', '3-Day Rain']:
        if c in df2.columns:
            df2[c] = pd.to_numeric(df2[c], errors='coerce')

    df2['date'] = pd.to_datetime(df2['Date'], errors='coerce') if 'Date' in df2.columns else pd.NaT
    df2['rainPast3Days'] = df2['3-Day Rain'] if '3-Day Rain' in df2.columns else np.nan

    # Use first site pair: Milton Road (Tag, Enterococcus)
    tag_col = 'Milton Road'
    ent_col = 'Enterococcus'
    out = pd.DataFrame({
        'date': df2['date'],
        'rainPast3Days': df2['rainPast3Days'],
        'tag': df2[tag_col] if tag_col in df2.columns else np.nan,
        'enterococcusRaw': pd.to_numeric(df2[ent_col], errors='coerce') if ent_col in df2.columns else np.nan,
    })

    def est(tag, x):
        if pd.isna(x):
            return np.nan
        if pd.isna(tag):
            return float(x)
        tag_str = str(tag).strip()
        if tag_str == '<':
            return float(x) / 2.0
        if tag_str == '>':
            return float(x)
        return float(x)

    out['enterococcusEst'] = [est(t, x) for t, x in zip(out['tag'], out['enterococcusRaw'])]

    out = out.dropna(subset=['date', 'rainPast3Days', 'enterococcusEst']).copy()
    out['Community'] = 'Quincy'
    out['Beach Name'] = 'Wollaston Beach'

    return out[['Community', 'Beach Name', 'date', 'rainPast3Days', 'enterococcusEst']]
